using System.Text.Json;
using DantesRoleplay.Actions; using DantesRoleplay.DataAccess; using DantesRoleplay.DataAccess.Catalog; using DantesRoleplay.Effects; using DantesRoleplay.Mechanics; using DantesRoleplay.Operations; using DantesRoleplay.RuleAccess;
namespace DantesRoleplay.Tests;
public sealed class CatalogFeature23Slice6Tests:IDisposable{
 readonly SqliteFixture f=new(); readonly string copy=Path.Combine(Path.GetTempPath(),$"f23s6-{Guid.NewGuid():n}"); public void Dispose(){f.Dispose();if(Directory.Exists(copy))Directory.Delete(copy,true);}
 [Fact] public async Task Explicit_size_and_strength_derive_srd_capacities_with_composed_burden(){await using var db=f.CreateContext();var w=new WorldStore(db);var m=new MechanicStore(db);Copy(Catalog(),copy);Assert.False((await new CatalogImporter(db,m,new ProcedureStore(db),w).ApplyAsync(copy,new CatalogImportOptions())).Aborted);var r=Runner(db,w,m);foreach(var x in new[]{("tiny",75), ("small",150), ("medium",150), ("large",300), ("huge",600), ("gargantuan",1200)}){var id="f23.s6."+x.Item1;await w.CreateEntityAsync(x.Item1,id);await w.SetComponentAsync(id,"dnd2024.abilities","""{"str":10,"dex":10,"con":10,"int":10,"wis":10,"cha":10}""");var recorded=await Run(r,"record creature size","{"+"\"size\":\""+x.Item1+"\"}",("creature",id));Assert.True(recorded.Ok,recorded.Error?.Why);var read=await Run(r,"derive carrying capacity","{}",("creature",id));Assert.True(read.Ok,read.Error?.Why);using var d=JsonDocument.Parse(read.Output!.Data);Assert.Equal(x.Item2,d.RootElement.GetProperty("carryingCapacityPounds").GetProperty("numerator").GetInt32());Assert.Equal(1,d.RootElement.GetProperty("carryingCapacityPounds").GetProperty("denominator").GetInt32());Assert.Equal(x.Item2*2,d.RootElement.GetProperty("dragLiftPushCapacityPounds").GetProperty("numerator").GetInt32());}var duplicate=await Run(r,"record creature size","""{"size":"medium"}""",("creature","f23.s6.tiny"));Assert.False(duplicate.Ok);await w.CreateEntityAsync("Unknown","f23.s6.unknown");await w.SetComponentAsync("f23.s6.unknown","dnd2024.abilities","""{"str":10,"dex":10,"con":10,"int":10,"wis":10,"cha":10}""");Assert.False((await Run(r,"derive carrying capacity","{}",("creature","f23.s6.unknown"))).Ok);}
 static Task<ActionRunResult> Run(ActionRunner r,string i,string input,params(string role,string id)[] x)=>r.RunAsync(new ActionRequest{Intent=i,Input=input,Seed=6,RoleEntityIds=x.ToDictionary(a=>a.role,a=>a.id,StringComparer.Ordinal)});static ActionRunner Runner(DantesRoleplayDbContext d,WorldStore w,MechanicStore m)=>new(d,m,new ProjectionResolver(d),new JintMechanicEngine(),new EffectApplier(d,w),new OperationLog(d),new MechanicComposer(m,new ProjectionResolver(d),new JintMechanicEngine()));static string Catalog(){for(var x=new DirectoryInfo(AppContext.BaseDirectory);x is not null;x=x.Parent)if(File.Exists(Path.Combine(x.FullName,"catalog","manifest.json")))return Path.Combine(x.FullName,"catalog");throw new DirectoryNotFoundException();}static void Copy(string s,string t){foreach(var d in Directory.EnumerateDirectories(s,"*",SearchOption.AllDirectories))Directory.CreateDirectory(Path.Combine(t,Path.GetRelativePath(s,d)));Directory.CreateDirectory(t);foreach(var x in Directory.EnumerateFiles(s,"*",SearchOption.AllDirectories))File.Copy(x,Path.Combine(t,Path.GetRelativePath(s,x)));}}
